1	import * as BABYLON from 'babylonjs';
2	import 'babylonjs-loaders';
3	import headModelUrl from '@/assets/models/aetheris-4.glb?url';
4	import {
5	  LINE_TYPES,
6	  DEFAULT_LINE_VISIBILITY,
7	  resolveLineType,
8	  type LineTypeId,
9	  type LineTypeVisibility,
10	} from './gcodeLineTypes';
11	import { detectGeneratorSignature, guessGeneratorFromFeature, type GCodeGenerator } from './gcodeGenerator';
12	
13	/**
14	 * Parseur G-code + calque Babylon de prévisualisation. Deux familles de fichiers :
15	 *
16	 * 1. G-code polaire 4 axes de l'Apex (reconnu à la présence d'un mot B dans les déplacements) :
17	 *    `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
18	 *    - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
19	 *    - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
20	 *      la continuité angulaire, un C > 360 ou négatif est normal).
21	 *    - Z : hauteur (mm). B : inclinaison de la tête vers +R (à l'opposé de l'axe de rotation), en
22	 *      degrés.
23	 *    - R/Z sont les positions machine du PIVOT de l'axe B, pas de la buse : la pointe de buse est
24	 *      à NOZZLE_PIVOT_MM sous le pivot, le long de l'axe de la tête (cf. `nozzleTip`).
25	 *    - La matière est stockée en repère plateau sous un noeud dont la rotation suit le C courant :
26	 *      plateau et matière tournent ensemble, la tête reste dans le demi-plan machine (R, 0, Z).
27	 *    - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
28	 *      segments sont subdivisés en angle pour suivre l'arc réellement parcouru.
29	 *
30	 * 2. G-code cartésien de slicer (Orca, Bambu, Anycubic Slicer Next, Creality Print, PrusaSlicer,
31	 *    Cura, Simplify3D…) : G0/G1, arcs G2/G3 (I/J ou R), G90/G91, M82/M83, G92, G10/G11, G20/G21,
32	 *    G28. La pièce est recentrée sur le centre du plateau d'origine (`printable_area`/`bed_shape`
33	 *    de l'en-tête, sinon centre de la pièce) ; plateau fixe, la tête se déplace en X/Y/Z.
34	 *
35	 * Dans les deux cas, les types de ligne (`;TYPE:`, `; FEATURE:`…), essuyages (`;WIPE_START`),
36	 * rétractions et coutures sont reconnus pour la légende et la coloration (cf. gcodeLineTypes.ts).
37	 */
38	
39	export type GCodeKind = 'polar' | 'cartesian';
40	
41	export interface GCodeMove {
42	  /** Mot X : rayon R (polaire) ou X recentré sur le plateau (cartésien), en mm. */
43	  x: number;
44	  /** Mot Y : angle C du plateau en degrés (polaire) ou Y recentré sur le plateau en mm (cartésien). */
45	  y: number;
46	  z: number;
47	  /** Inclinaison de la tête (degrés) ; toujours 0 en cartésien. */
48	  b: number;
49	  extruding: boolean;
50	  type: LineTypeId;
51	}
52	
53	export interface LineTypeStat {
54	  /** Temps machine (s). */
55	  time: number;
56	  /** Filament déposé (mm de filament, hors réinjection après rétraction). */
57	  filamentMm: number;
58	  massG: number;
59	}
60	
61	export type MarkerTypeId = Extract<LineTypeId, 'retraction' | 'unretraction' | 'seam'>;
62	
63	export interface ParsedGCode {
64	  kind: GCodeKind;
65	  moves: GCodeMove[];
66	  /** Temps machine cumulé (s) à l'arrivée de chaque mouvement (`times[0] = 0`), déduit de la
67	   * distance parcourue par la buse et de l'avance F — cf. `timeAtIndex`/`indexAtTime`. */
68	  times: Float64Array;
69	  minZ: number;
70	  maxZ: number;
71	  maxR: number;
72	  minC: number;
73	  maxC: number;
74	  extrudingCount: number;
75	  lineStats: Record<LineTypeId, LineTypeStat>;
76	  /** Marqueurs ponctuels, par index croissant du mouvement à la FIN duquel ils se trouvent. */
77	  markers: Record<MarkerTypeId, Uint32Array>;
78	  /** Logiciel qui a le plus probablement produit le fichier, null si rien ne permet de le dire. */
79	  generator: GCodeGenerator | null;
80	  /** Imprimante cible déclarée dans l'en-tête, si présente. */
81	  printer: string | null;
82	  /** Cartésien : dépôts à Z variable au sein d'une couche (tranchage courbe, vase…) — l'angle
83	   * dynamique de la conversion polaire y est utile. */
84	  nonPlanar: boolean;
85	  /** Cartésien : centre du plateau d'origine (coordonnées du fichier), soustrait des X/Y. */
86	  bedCenter: { x: number; y: number };
87	  /** Fichier issu de la conversion polaire d'Apex (`; apex_conversion_mode = …`), sinon null. */
88	  conversion: ConversionMode | null;
89	  /** Cartésien : dépôts qui finissent hors du plateau de l'Apex (PLATE_RADIUS_MM autour du centre)
90	   * — indices croissants — et nombre de traits (suites continues) qu'ils forment. */
91	  offPlate: { moves: Uint32Array; traits: number };
92	}
93	
94	/** Rayon du plateau de l'Apex (mm), cf. RADIUS dans Viewport3D.tsx. */
95	export const PLATE_RADIUS_MM = 125;
96	
97	export type ConversionMode = 'polar' | 'dynamic';
98	
99	const DEG2RAD = Math.PI / 180;
100	// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
101	// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
102	const MAX_SUBSEGMENT_DEG = 0.5;
103	/** Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
104	 * boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite). */
105	export const SUSPICIOUS_C_RANGE_DEG = 720;
106	
107	/** Distance entre la pointe de buse et le pivot de l'axe B (mm), le long de l'axe de la tête. */
108	export const NOZZLE_PIVOT_MM = 46;
109	
110	/**
111	 * Pointe de buse (rayon, hauteur) dans le demi-plan machine, depuis la position du pivot (R, Z)
112	 * et l'inclinaison B (radians). La tête penche vers +R (cf. `headDir` dans `apply`), donc la
113	 * buse, SOUS le pivot, part vers −R. Z est calé pour que tête droite (B = 0) la buse soit
114	 * exactement à Z : seul l'écart dû à l'inclinaison, L·(1 − cos B), s'ajoute en hauteur.
115	 */
116	function nozzleTip(r: number, z: number, bRad: number, out: { r: number; z: number }) {
117	  out.r = r - NOZZLE_PIVOT_MM * Math.sin(bRad);
118	  out.z = z + NOZZLE_PIVOT_MM * (1 - Math.cos(bRad));
119	  return out;
120	}
121	
122	/** Avance (mm/min) supposée tant que le fichier n'a pas encore donné de F. */
123	const DEFAULT_FEED_MM_MIN = 1500;
124	/** Durée plancher d'un mouvement (s) : un mouvement quasi immobile pour la buse (rotation autour
125	 * du centre, consigne répétée) prend tout de même un instant. */
126	const MIN_MOVE_S = 1e-3;
127	/** Filament par défaut quand l'en-tête ne le précise pas : PLA 1,75 mm. */
128	const DEFAULT_FILAMENT_DIAMETER_MM = 1.75;
129	const DEFAULT_FILAMENT_DENSITY_G_CM3 = 1.24;
130	/** Longueur supposée d'une rétraction firmware (G10) quand l'en-tête ne donne pas `retraction_length`. */
131	const DEFAULT_FIRMWARE_RETRACT_MM = 1;
132	/** Découpage des arcs G2/G3 en segments droits : corde et angle maximaux. */
133	const ARC_MAX_CHORD_MM = 0.5;
134	const ARC_MAX_STEP_RAD = 10 * DEG2RAD;
135	const ARC_MAX_SEGMENTS = 720;
136	/** Variation de E (mm) en dessous de laquelle on la considère nulle (arrondis des fichiers). */
137	const E_EPS = 1e-6;
138	/** Cinématique supposée (cartésien) tant que le fichier ne la fixe pas (M204, M205,
139	 * SET_VELOCITY_LIMIT) : accélération en mm/s², jerk / vitesse de coin en mm/s. */
140	const DEFAULT_ACCEL = 1000;
141	const DEFAULT_JERK = 8;
142	
143	const COMMAND_RE = /^([GM])(\d+)(?:\.\d+)?/;
144	const WORD_RE = /([A-Z])\s*([-+]?(?:\d+\.?\d*|\.\d+))/g;
145	const FEATURE_RE = /^\s*(?:TYPE|FEATURE)\s*[:\s]\s*(.+?)\s*$/i;
146	const WIPE_START_RE = /^\s*WIPE_START/i;
147	const WIPE_END_RE = /^\s*WIPE_END/i;
148	const ICESL_LAYER_RE = /^\s*<\/?layer>\s*$/i;
149	// Réglage d'en-tête `; clé = valeur` (Orca, Prusa), `; clé: valeur` (en-tête Orca), `; clé : valeur`
150	// (IceSL) ou `;CLÉ:valeur` (Cura).
151	const HEADER_RE = /^\s*([a-z][a-z0-9_.]*)\s*[:=]\s*(.*?)\s*$/i;
152	/** Signatures de slicer cherchées dans les commentaires précédant ce nombre de mouvements. */
153	const GENERATOR_SCAN_MOVES = 200;
154	// Klipper : SET_VELOCITY_LIMIT [VELOCITY=] [ACCEL=] [SQUARE_CORNER_VELOCITY=].
155	const VELOCITY_LIMIT_RE = /^SET_VELOCITY_LIMIT\b/i;
156	const VELOCITY_PARAM_RE = /\b(VELOCITY|ACCEL|ACCEL_TO_DECEL|SQUARE_CORNER_VELOCITY)\s*=\s*([\d.]+)/gi;
157	
158	const emptyStats = () =>
159	  Object.fromEntries(LINE_TYPES.map((t) => [t.id, { time: 0, filamentMm: 0, massG: 0 }])) as Record<LineTypeId, LineTypeStat>;
160	
161	/** Centre du rectangle englobant d'une liste de points « AxB,CxD,… » (printable_area, bed_shape). */
162	function shapeCenter(value: string) {
163	  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
164	  for (const pt of value.split(',')) {
165	    const [a, b] = pt.split('x').map(parseFloat);
166	    if (Number.isNaN(a) || Number.isNaN(b)) continue;
167	    minX = Math.min(minX, a); maxX = Math.max(maxX, a);
168	    minY = Math.min(minY, b); maxY = Math.max(maxY, b);
169	  }
170	  return minX <= maxX ? { x: (minX + maxX) / 2, y: (minY + maxY) / 2 } : null;
171	}
172	
173	/** Mots d'une ligne de commande (lettre → valeur), NaN si absent. */
174	interface Words {
175	  X: number; Y: number; Z: number; B: number; E: number; F: number;
176	  I: number; J: number; R: number; L: number; P: number; S: number; T: number;
177	}
178	const WORD_KEYS = ['X', 'Y', 'Z', 'B', 'E', 'F', 'I', 'J', 'R', 'L', 'P', 'S', 'T'] as const;
179	
180	/**
181	 * Temps machine cumulé d'une trajectoire cartésienne, comme le planificateur du firmware :
182	 * profil trapézoïdal par mouvement (accélération du moment), vitesses de jonction limitées par le
183	 * jerk (écart de vitesse par axe) puis propagées en arrière et en avant pour que chaque mouvement
184	 * puisse freiner à temps. Les mouvements d'extrudeur seul se font à l'arrêt, à l'avance F.
185	 */
186	function planCartesianTimes(
187	  moves: GCodeMove[],
188	  feeds: number[],
189	  eDeltas: number[],
190	  accels: number[],
191	  accelsToDecel: number[],
192	  jerks: number[],
193	  maxSpeed: number,
194	) {
195	  const n = moves.length;
196	  const times = new Float64Array(n);
197	  const len = new Float64Array(n);
198	  const dirs = new Float64Array(n * 3);
199	  for (let k = 1; k < n; k++) {
200	    const a = moves[k - 1], m = moves[k];
201	    const dx = m.x - a.x, dy = m.y - a.y, dz = m.z - a.z;
202	    const d = Math.hypot(dx, dy, dz);
203	    len[k] = d;
204	    if (d > 1e-9) {
205	      dirs[k * 3] = dx / d;
206	      dirs[k * 3 + 1] = dy / d;
207	      dirs[k * 3 + 2] = dz / d;
208	    }
209	  }
210	  const moving = (k: number) => k >= 1 && k < n && len[k] > 1e-9;
211	  const vmax = (k: number) => Math.min(feeds[k] / 60, maxSpeed);
212	
213	  // v[k] : vitesse au début du mouvement k (= fin du mouvement k − 1) ; v[n] : arrêt final.
214	  const v = new Float64Array(n + 1);
215	  for (let k = 1; k < n; k++) {
216	    if (!moving(k)) continue;
217	    let maxDiff = 0;
218	    let limit = vmax(k);
219	    for (let i = 0; i < 3; i++) {
220	      const prev = moving(k - 1) ? dirs[(k - 1) * 3 + i] : 0;
221	      maxDiff = Math.max(maxDiff, Math.abs(dirs[k * 3 + i] - prev));
222	    }
223	    if (moving(k - 1)) limit = Math.min(limit, vmax(k - 1));
224	    if (maxDiff > 1e-9) limit = Math.min(limit, jerks[k] / maxDiff);
225	    v[k] = limit;
226	  }
227	  for (let k = n - 1; k >= 1; k--) {
228	    if (moving(k)) v[k] = Math.min(v[k], Math.sqrt(v[k + 1] ** 2 + 2 * accels[k] * len[k]));
229	  }
230	  for (let k = 1; k < n; k++) {
231	    if (moving(k) && moving(k + 1)) v[k + 1] = Math.min(v[k + 1], Math.sqrt(v[k] ** 2 + 2 * accels[k] * len[k]));
232	  }
233	
234	  for (let k = 1; k < n; k++) {
235	    let dt: number;
236	    if (!moving(k)) {
237	      dt = Math.abs(eDeltas[k]) / (feeds[k] / 60);
238	    } else {
239	      const a = accels[k], d = len[k];
240	      const v0 = v[k];
241	      const v1 = moving(k + 1) ? v[k + 1] : 0;
242	      const vm = vmax(k);
243	      // Klipper (ACCEL_TO_DECEL) : la vitesse de croisière atteignable est plafonnée par une
244	      // accélération « lissée » plus faible, sans changer les rampes elles-mêmes.
245	      const reach = Math.min(a, accelsToDecel[k]) * d + (v0 * v0 + v1 * v1) / 2;
246	      const vp = Math.sqrt(Math.max(Math.min(vm * vm, reach), v0 * v0, v1 * v1));
247	      const cruise = Math.max(0, d - (vp * vp - v0 * v0) / (2 * a) - (vp * vp - v1 * v1) / (2 * a));
248	      dt = (vp - v0) / a + (vp - v1) / a + cruise / vp;
249	    }
250	    times[k] = times[k - 1] + Math.max(MIN_MOVE_S, dt);
251	  }
252	  return times;
253	}
254	
255	export function parseGCode(text: string): ParsedGCode {
256	  const moves: GCodeMove[] = [];
257	  const feeds: number[] = [];
258	  const eDeltas: number[] = [];
259	  const deposits: number[] = [];
260	  const retractionAt: number[] = [];
261	  const unretractionAt: number[] = [];
262	  const seamAt: number[] = [];
263	
264	  let x = 0, y = 0, z = 0, b = 0;
265	  let feed = DEFAULT_FEED_MM_MIN; // modal, comme le firmware
266	  let unit = 1;
267	  let relativeXYZ = false;
268	  let relativeE = false;
269	  // Position E absolue connue (mode M82) ; inconnue avant la première valeur E, comme avant.
270	  let eAbs: number | null = null;
271	  let feature: LineTypeId = 'custom';
272	  let inWipe = false;
273	  // Filament actuellement rétracté (mm) : la part d'une extrusion qui ne fait que le réinjecter
274	  // n'est pas du dépôt.
275	  let retracted = 0;
276	  let prevRetracting = false;
277	  let prevRestoring = false;
278	  let polar = false;
279	  let extrudingCount = 0;
280	  let filamentDiameter = DEFAULT_FILAMENT_DIAMETER_MM;
281	  let filamentDensity = DEFAULT_FILAMENT_DENSITY_G_CM3;
282	  let firmwareRetract = DEFAULT_FIRMWARE_RETRACT_MM;
283	  let bedCenter: { x: number; y: number } | null = null;
284	  // Cinématique courante (cartésien), par mouvement : accélération d'impression/de déplacement
285	  // (M204 P/T, ou S pour les deux) et jerk / vitesse de coin (M205 X, SQUARE_CORNER_VELOCITY).
286	  const accels: number[] = [];
287	  const jerks: number[] = [];
288	  const accelsToDecel: number[] = [];
289	  let accelToDecel = Infinity;
290	  let accelPrint = DEFAULT_ACCEL;
291	  let accelTravel = DEFAULT_ACCEL;
292	  let jerk = DEFAULT_JERK;
293	  let maxSpeed = Infinity;
294	  let headerMaxSpeed = Infinity;
295	  // Plateau décrit par dimensions (IceSL : bed_size_x_mm/bed_size_y_mm, origine au centre si rond).
296	  let bedSizeX = 0;
297	  let bedSizeY = 0;
298	  let bedCircular = false;
299	  let printer: string | null = null;
300	  let signature: string | null = null;
301	  let featureStyleGuess: string | null = null;
302	  let iceSLLayers = false;
303	  let conversion: ConversionMode | null = null;
304	
305	  const handleComment = (comment: string) => {
306	    if (WIPE_START_RE.test(comment)) { inWipe = true; return; }
307	    if (WIPE_END_RE.test(comment)) { inWipe = false; return; }
308	    if (!signature && moves.length < GENERATOR_SCAN_MOVES) signature = detectGeneratorSignature(comment);
309	    const feat = FEATURE_RE.exec(comment);
310	    if (feat && !comment.includes('=')) {
311	      feature = resolveLineType(feat[1]);
312	      featureStyleGuess ??= guessGeneratorFromFeature(feat[1], !/^\s*(?:TYPE|FEATURE)\s*:/i.test(comment));
313	      return;
314	    }
315	    if (ICESL_LAYER_RE.test(comment)) { iceSLLayers = true; return; }
316	    const header = HEADER_RE.exec(comment);
317	    if (!header) return;
318	    const key = header[1].toLowerCase();
319	    const raw = header[2];
320	    const value = parseFloat(raw);
321	    switch (key) {
322	      case 'printable_area':
323	      case 'bed_shape':
324	        bedCenter = shapeCenter(raw) ?? bedCenter;
325	        break;
326	      case 'bed_size_x_mm': if (value > 0) bedSizeX = value; break;
327	      case 'bed_size_y_mm': if (value > 0) bedSizeY = value; break;
328	      case 'bed_circular': bedCircular = /^true/i.test(raw); break;
329	      case 'filament_diameter':
330	      case 'filament_diameter_mm_0':
331	        if (value > 0) filamentDiameter = value;
332	        break;
333	      case 'filament_density': if (value > 0) filamentDensity = value; break;
334	      case 'machine_max_speed_x': if (value > 0) headerMaxSpeed = value; break;
335	      case 'retraction_length': if (value > 0) firmwareRetract = value; break;
336	      case 'printer_model':
337	      case 'printer':
338	      case 'target_machine.name':
339	        if (!printer && raw) printer = raw;
340	        break;
341	      case 'apex_conversion_mode':
342	        if (raw === 'polar' || raw === 'dynamic') conversion = raw;
343	        break;
344	    }
345	  };
346	
347	  const push = (nx: number, ny: number, nz: number, nb: number, de: number) => {
348	    const moved = nx !== x || ny !== y || nz !== z || nb !== b;
349	    let restore = 0;
350	    let deposit = 0;
351	    if (de > E_EPS) {
352	      restore = Math.min(de, retracted);
353	      retracted -= restore;
354	      deposit = de - restore;
355	    } else if (de < -E_EPS) {
356	      retracted -= de;
357	    }
358	
359	    let type: LineTypeId;
360	    let extruding = false;
361	    if (inWipe && moved) type = 'wipe';
362	    else if (moved && deposit > E_EPS) { type = feature; extruding = true; }
363	    else if (moved) type = 'travel';
364	    else if (de < -E_EPS) type = 'retraction';
365	    else if (de > E_EPS) type = 'unretraction';
366	    else type = 'travel';
367	
368	    const k = moves.length;
369	    const retracting = de < -E_EPS;
370	    const restoring = restore > E_EPS;
371	    if (retracting && !prevRetracting) retractionAt.push(k);
372	    if (restoring && !prevRestoring) unretractionAt.push(k);
373	    prevRetracting = retracting;
374	    prevRestoring = restoring;
375	    // Couture : début d'une boucle de paroi extérieure, à la position d'où part ce mouvement.
376	    if (type === 'outerWall' && k > 0 && moves[k - 1].type !== 'outerWall') seamAt.push(k - 1);
377	
378	    if (extruding) extrudingCount++;
379	    moves.push({ x: nx, y: ny, z: nz, b: nb, extruding, type });
380	    feeds.push(feed);
381	    eDeltas.push(de);
382	    deposits.push(extruding ? deposit : 0);
383	    accels.push(extruding ? accelPrint : accelTravel);
384	    jerks.push(jerk);
385	    accelsToDecel.push(accelToDecel);
386	    x = nx; y = ny; z = nz; b = nb;
387	  };
388	
389	  const w = {} as Words;
390	  const readWords = (args: string) => {
391	    for (const key of WORD_KEYS) w[key] = NaN;
392	    WORD_RE.lastIndex = 0;
393	    let m: RegExpExecArray | null;
394	    while ((m = WORD_RE.exec(args)) !== null) {
395	      if (m[1] in w) w[m[1] as keyof Words] = parseFloat(m[2]);
396	    }
397	  };
398	  const has = (v: number) => !Number.isNaN(v);
399	  const axis = (current: number, word: number, scale: number) =>
400	    has(word) ? (relativeXYZ ? current + word * scale : word * scale) : current;
401	  const extrusionDelta = () => {
402	    if (!has(w.E)) return 0;
403	    const e = w.E * unit;
404	    if (relativeXYZ || relativeE) return e;
405	    const de = eAbs === null ? 0 : e - eAbs;
406	    eAbs = e;
407	    return de;
408	  };
409	
410	  for (const rawLine of text.split('\n')) {
411	    const semi = rawLine.indexOf(';');
412	    if (semi >= 0) handleComment(rawLine.slice(semi + 1));
413	    let code = semi >= 0 ? rawLine.slice(0, semi) : rawLine;
414	    if (code.includes('(')) {
415	      code = code.replace(/\(([^)]*)\)/g, (_, comment: string) => { handleComment(comment); return ' '; });
416	    }
417	    code = code.trim().toUpperCase();
418	    if (!code) continue;
419	    if (VELOCITY_LIMIT_RE.test(code)) {
420	      VELOCITY_PARAM_RE.lastIndex = 0;
421	      let p: RegExpExecArray | null;
422	      while ((p = VELOCITY_PARAM_RE.exec(code)) !== null) {
423	        const value = parseFloat(p[2]);
424	        if (!(value > 0)) continue;
425	        if (p[1] === 'ACCEL') accelPrint = accelTravel = value;
426	        else if (p[1] === 'ACCEL_TO_DECEL') accelToDecel = value;
427	        else if (p[1] === 'VELOCITY') maxSpeed = value;
428	        else jerk = value;
429	      }
430	      continue;
431	    }
432	    const cmd = COMMAND_RE.exec(code);
433	    if (!cmd) continue;
434	    const num = parseInt(cmd[2], 10);
435	    readWords(code.slice(cmd[0].length));
436	
437	    if (cmd[1] === 'M') {
438	      if (num === 82) relativeE = false;
439	      else if (num === 83) relativeE = true;
440	      else if (num === 203 && w.X > 0) maxSpeed = w.X;
441	      else if (num === 204) {
442	        if (w.S > 0) accelPrint = accelTravel = w.S;
443	        if (w.P > 0) accelPrint = w.P;
444	        if (w.T > 0) accelTravel = w.T;
445	      } else if (num === 205 && w.X > 0) jerk = w.X;
446	      continue;
447	    }
448	
449	    switch (num) {
450	      case 0:
451	      case 1: {
452	        if (has(w.B)) polar = true;
453	        if (has(w.F) && w.F > 0) feed = w.F * unit;
454	        if (!has(w.X) && !has(w.Y) && !has(w.Z) && !has(w.B) && !has(w.E)) break;
455	        const nx = axis(x, w.X, unit);
456	        const ny = axis(y, w.Y, unit);
457	        const nz = axis(z, w.Z, unit);
458	        const nb = axis(b, w.B, 1);
459	        push(nx, ny, nz, nb, extrusionDelta());
460	        break;
461	      }
462	      case 2:
463	      case 3: {
464	        if (has(w.F) && w.F > 0) feed = w.F * unit;
465	        const ex = axis(x, w.X, unit);
466	        const ey = axis(y, w.Y, unit);
467	        const ez = axis(z, w.Z, unit);
468	        const de = extrusionDelta();
469	        const ccw = num === 3;
470	        let cx: number, cy: number;
471	        if (has(w.I) || has(w.J)) {
472	          cx = x + (has(w.I) ? w.I * unit : 0);
473	          cy = y + (has(w.J) ? w.J * unit : 0);
474	        } else if (has(w.R)) {
475	          const r = w.R * unit;
476	          const dx = ex - x, dy = ey - y;
477	          const d = Math.hypot(dx, dy);
478	          if (d < 1e-9 || Math.abs(r) < d / 2) { push(ex, ey, ez, b, de); break; }
479	          const h = Math.sqrt(r * r - (d * d) / 4) * (ccw ? 1 : -1) * (r > 0 ? 1 : -1);
480	          cx = (x + ex) / 2 - (dy / d) * h;
481	          cy = (y + ey) / 2 + (dx / d) * h;
482	        } else {
483	          push(ex, ey, ez, b, de);
484	          break;
485	        }
486	        const radius = Math.hypot(x - cx, y - cy);
487	        const a0 = Math.atan2(y - cy, x - cx);
488	        let sweep = Math.atan2(ey - cy, ex - cx) - a0;
489	        if (ccw) { while (sweep <= 1e-9) sweep += 2 * Math.PI; }
490	        else { while (sweep >= -1e-9) sweep -= 2 * Math.PI; }
491	        const n = Math.min(ARC_MAX_SEGMENTS, Math.max(
492	          1,
493	          Math.ceil((Math.abs(sweep) * radius) / ARC_MAX_CHORD_MM),
494	          Math.ceil(Math.abs(sweep) / ARC_MAX_STEP_RAD),
495	        ));
496	        const z0 = z;
497	        for (let i = 1; i <= n; i++) {
498	          if (i === n) { push(ex, ey, ez, b, de / n); break; }
499	          const a = a0 + (sweep * i) / n;
500	          push(cx + radius * Math.cos(a), cy + radius * Math.sin(a), z0 + ((ez - z0) * i) / n, b, de / n);
501	        }
502	        break;
503	      }
504	      case 10:
505	        // G10 sans L/P : rétraction firmware (avec L/P : réglage d'origine CNC, ignoré).
506	        if (!has(w.L) && !has(w.P)) push(x, y, z, b, -firmwareRetract);
507	        break;
508	      case 11:
509	        push(x, y, z, b, firmwareRetract);
510	        break;
511	      case 20: unit = 25.4; break;
512	      case 21: unit = 1; break;
513	      case 28: {
514	        const all = !has(w.X) && !has(w.Y) && !has(w.Z);
515	        if (all || has(w.X)) x = 0;
516	        if (all || has(w.Y)) y = 0;
517	        if (all || has(w.Z)) z = 0;
518	        break;
519	      }
520	      case 90: relativeXYZ = false; break;
521	      case 91: relativeXYZ = true; break;
522	      case 92:
523	        if (has(w.X)) x = w.X * unit;
524	        if (has(w.Y)) y = w.Y * unit;
525	        if (has(w.Z)) z = w.Z * unit;
526	        if (has(w.B)) b = w.B;
527	        if (has(w.E)) eAbs = w.E * unit;
528	        break;
529	    }
530	  }
531	
532	  const kind: GCodeKind = polar ? 'polar' : 'cartesian';
533	
534	  let usedCenter = { x: 0, y: 0 };
535	  let nonPlanar = false;
536	  const offPlateMoves: number[] = [];
537	  let offPlateTraits = 0;
538	  if (kind === 'cartesian' && moves.length) {
539	    // Non plan : plus de 5 % des dépôts changent de Z en cours de trajet.
540	    let zVarying = 0;
541	    for (let k = 1; k < moves.length; k++) {
542	      if (moves[k].extruding && Math.abs(moves[k].z - moves[k - 1].z) > 1e-4) zVarying++;
543	    }
544	    nonPlanar = extrudingCount > 0 && zVarying / extrudingCount > 0.05;
545	
546	    let center: { x: number; y: number } | null = bedCenter;
547	    if (!center && bedCircular) center = { x: 0, y: 0 };
548	    if (!center && bedSizeX > 0 && bedSizeY > 0) center = { x: bedSizeX / 2, y: bedSizeY / 2 };
549	    if (!center) {
550	      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
551	      const anyExtruding = extrudingCount > 0;
552	      for (const mv of moves) {
553	        if (anyExtruding && !mv.extruding) continue;
554	        minX = Math.min(minX, mv.x); maxX = Math.max(maxX, mv.x);
555	        minY = Math.min(minY, mv.y); maxY = Math.max(maxY, mv.y);
556	      }
557	      center = { x: (minX + maxX) / 2, y: (minY + maxY) / 2 };
558	    }
559	    usedCenter = center;
560	    for (const mv of moves) {
561	      mv.x -= center.x;
562	      mv.y -= center.y;
563	      mv.b = 0;
564	    }
565	    for (let k = 1; k < moves.length; k++) {
566	      const mv = moves[k];
567	      if (!mv.extruding || Math.hypot(mv.x, mv.y) <= PLATE_RADIUS_MM) continue;
568	      if (offPlateMoves[offPlateMoves.length - 1] !== k - 1) offPlateTraits++;
569	      offPlateMoves.push(k);
570	    }
571	  }
572	
573	  // Durée de chaque mouvement. Sans ça, la lecture avancerait d'un nombre fixe de mouvements par
574	  // seconde : une longue ligne droite serait franchie aussi vite qu'un segment de 0,1 mm.
575	  //  - Cartésien : planificateur de vitesses (accélérations, jerk), cf. `planCartesianTimes`.
576	  //  - Polaire : distance parcourue par la pointe de buse relativement au plateau, à l'avance F.
577	  // Mouvement d'extrudeur seul : longueur de filament poussée/tirée, à l'avance F.
578	  let times: Float64Array;
579	  if (kind === 'cartesian') {
580	    const cap = Math.min(maxSpeed, headerMaxSpeed);
581	    times = planCartesianTimes(moves, feeds, eDeltas, accels, accelsToDecel, jerks, cap);
582	  } else {
583	    times = new Float64Array(moves.length);
584	    const tipA = { r: 0, z: 0 };
585	    const tipB = { r: 0, z: 0 };
586	    for (let k = 1; k < moves.length; k++) {
587	      const a = moves[k - 1];
588	      const m = moves[k];
589	      nozzleTip(a.x, a.z, a.b * DEG2RAD, tipA);
590	      nozzleTip(m.x, m.z, m.b * DEG2RAD, tipB);
591	      const dr = tipB.r - tipA.r;
592	      const dz = tipB.z - tipA.z;
593	      const arc = ((Math.abs(tipA.r) + Math.abs(tipB.r)) / 2) * (m.y - a.y) * DEG2RAD;
594	      let dist = Math.sqrt(dr * dr + dz * dz + arc * arc);
595	      if (dist < 1e-9) dist = Math.abs(eDeltas[k]);
596	      times[k] = times[k - 1] + Math.max(MIN_MOVE_S, dist / (feeds[k] / 60));
597	    }
598	  }
599	  const lineStats = emptyStats();
600	  for (let k = 1; k < moves.length; k++) {
601	    const stat = lineStats[moves[k].type];
602	    stat.time += times[k] - times[k - 1];
603	    stat.filamentMm += deposits[k];
604	  }
605	  const gPerMm = Math.PI * (filamentDiameter / 2) ** 2 * filamentDensity / 1000;
606	  for (const stat of Object.values(lineStats)) stat.massG = stat.filamentMm * gPerMm;
607	
608	  // Bornes en Z/R de la pointe de buse (ce qui est affiché), pas du pivot.
609	  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
610	  const tip = { r: 0, z: 0 };
611	  for (const mv of moves) {
612	    if (kind === 'polar') {
613	      nozzleTip(mv.x, mv.z, mv.b * DEG2RAD, tip);
614	      if (Math.abs(tip.r) > maxR) maxR = Math.abs(tip.r);
615	      if (mv.y < minC) minC = mv.y;
616	      if (mv.y > maxC) maxC = mv.y;
617	    } else {
618	      tip.z = mv.z;
619	      maxR = Math.max(maxR, Math.hypot(mv.x, mv.y));
620	    }
621	    if (tip.z < minZ) minZ = tip.z;
622	    if (tip.z > maxZ) maxZ = tip.z;
623	  }
624	  if (!moves.length) { minZ = maxZ = 0; }
625	  if (minC > maxC) { minC = maxC = 0; }
626	
627	  let generator: GCodeGenerator | null = null;
628	  if (signature) generator = { name: signature, inferred: false };
629	  else if (kind === 'polar') generator = { name: 'Générateur Apex 4 axes', inferred: true };
630	  else if (featureStyleGuess) generator = { name: featureStyleGuess, inferred: true };
631	  else if (iceSLLayers) generator = { name: 'IceSL', inferred: true };
632	
633	  return {
634	    kind,
635	    moves,
636	    times,
637	    minZ,
638	    maxZ,
639	    maxR,
640	    minC,
641	    maxC,
642	    extrudingCount,
643	    lineStats,
644	    generator,
645	    printer,
646	    nonPlanar,
647	    bedCenter: usedCenter,
648	    conversion,
649	    offPlate: { moves: Uint32Array.from(offPlateMoves), traits: offPlateTraits },
650	    markers: {
651	      retraction: Uint32Array.from(retractionAt),
652	      unretraction: Uint32Array.from(unretractionAt),
653	      seam: Uint32Array.from(seamAt),
654	    },
655	  };
656	}
