658	/** Temps machine (s) à l'index de mouvement fractionnaire `t`. */
659	export function timeAtIndex(times: Float64Array, t: number) {
660	  const last = times.length - 1;
661	  const i = Math.max(0, Math.min(last, Math.floor(t)));
662	  if (i >= last) return times[last];
663	  return times[i] + (times[i + 1] - times[i]) * (t - i);
664	}
665	
666	/** Index de mouvement fractionnaire atteint au temps machine `s` (inverse de `timeAtIndex`). */
667	export function indexAtTime(times: Float64Array, s: number) {
668	  const last = times.length - 1;
669	  if (s <= 0) return 0;
670	  if (s >= times[last]) return last;
671	  let lo = 0, hi = last; // times[lo] <= s < times[hi]
672	  while (hi - lo > 1) {
673	    const mid = (lo + hi) >> 1;
674	    if (times[mid] <= s) lo = mid; else hi = mid;
675	  }
676	  return lo + (s - times[lo]) / (times[hi] - times[lo]);
677	}
678	
679	/** Position machine (x, y, z, b) interpolée linéairement — comme le firmware — au temps `t`
680	 * exprimé en index de mouvement fractionnaire. */
681	export function stateAt(moves: GCodeMove[], t: number) {
682	  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
683	  const a = moves[i];
684	  const b = moves[Math.min(moves.length - 1, i + 1)];
685	  const f = Math.max(0, Math.min(1, t - i));
686	  return {
687	    x: a.x + (b.x - a.x) * f,
688	    y: a.y + (b.y - a.y) * f,
689	    z: a.z + (b.z - a.z) * f,
690	    b: a.b + (b.b - a.b) * f,
691	  };
692	}
693	
694	/**
695	 * Échantillonnage de la trajectoire en repère plateau (Babylon : y vers le haut) : position de la
696	 * pointe de buse et axe de la buse à la fraction `f` du mouvement `k`, et nombre de sous-segments
697	 * de chaque mouvement (subdivision angulaire en polaire, segment droit en cartésien).
698	 */
699	interface PathSampler {
700	  segments: Uint32Array;
701	  tip(k: number, f: number, out: BABYLON.Vector3): void;
702	  axis(k: number, f: number, out: BABYLON.Vector3): void;
703	}
704	
705	function createSampler(parsed: ParsedGCode): PathSampler {
706	  const { moves } = parsed;
707	  const segments = new Uint32Array(moves.length);
708	  const from = (k: number) => moves[k > 0 ? k - 1 : 0];
709	
710	  if (parsed.kind === 'cartesian') {
711	    segments.fill(1);
712	    return {
713	      segments,
714	      tip(k, f, out) {
715	        const a = from(k), m = moves[k];
716	        out.set(a.x + (m.x - a.x) * f, a.z + (m.z - a.z) * f, a.y + (m.y - a.y) * f);
717	      },
718	      axis(_k, _f, out) {
719	        out.set(0, 1, 0);
720	      },
721	    };
722	  }
723	
724	  for (let k = 1; k < moves.length; k++) {
725	    const dc = Math.abs(moves[k].y - moves[k - 1].y);
726	    segments[k] = Math.max(1, Math.ceil(dc / MAX_SUBSEGMENT_DEG));
727	  }
728	  const tipRZ = { r: 0, z: 0 };
729	  return {
730	    segments,
731	    // Interpolation en coordonnées pivot (comme le firmware), puis conversion à la buse.
732	    tip(k, f, out) {
733	      const a = from(k), m = moves[k];
734	      const c = (a.y + (m.y - a.y) * f) * DEG2RAD;
735	      nozzleTip(a.x + (m.x - a.x) * f, a.z + (m.z - a.z) * f, (a.b + (m.b - a.b) * f) * DEG2RAD, tipRZ);
736	      out.set(tipRZ.r * Math.cos(c), tipRZ.z, tipRZ.r * Math.sin(c));
737	    },
738	    // Axe de buse (vers le haut de la tête) : (sin B, cos B) dans le demi-plan machine, dont la
739	    // direction radiale est à l'angle C du dépôt.
740	    axis(k, f, out) {
741	      const a = from(k), m = moves[k];
742	      const c = (a.y + (m.y - a.y) * f) * DEG2RAD;
743	      const b = (a.b + (m.b - a.b) * f) * DEG2RAD;
744	      out.set(Math.sin(b) * Math.cos(c), Math.cos(b), Math.sin(b) * Math.sin(c));
745	    },
746	  };
747	}
