749	interface PathMesh {
750	  mesh: BABYLON.Mesh | null;
751	  /** Nombre d'indices à dessiner une fois le mouvement k terminé. */
752	  cumIndices: Uint32Array;
753	  /** Nombre d'indices par sous-segment : granularité de l'affichage d'un mouvement partiel. */
754	  indicesPerStep: number;
755	}
756	
757	/** Section du cordon déposé (mm) : largeur de part et d'autre de la trajectoire, et épaisseur le
758	 * long de l'axe de la buse. Valeurs nominales (pas de largeur/hauteur de couche lue). */
759	export const BEAD_WIDTH_MM = 0.6;
760	export const BEAD_HEIGHT_MM = 0.3;
761	/** Nombre de facettes de la section du cordon. */
762	const TUBE_SIDES = 6;
763	/** Diamètre des sphères des marqueurs ponctuels (rétractions, coutures). */
764	const MARKER_DIAMETER_MM = 0.8;
765	
766	const RING_COS = Float32Array.from({ length: TUBE_SIDES }, (_, i) => Math.cos((i / TUBE_SIDES) * Math.PI * 2));
767	const RING_SIN = Float32Array.from({ length: TUBE_SIDES }, (_, i) => Math.sin((i / TUBE_SIDES) * Math.PI * 2));
768	
769	/**
770	 * Écrit l'anneau n° `ring` du cordon (TUBE_SIDES sommets et normales) : ellipse centrée en c,
771	 * perpendiculaire à la tangente unitaire t, écrasée le long de l'axe de buse a (BEAD_HEIGHT_MM)
772	 * et large de BEAD_WIDTH_MM sur le côté.
773	 */
774	function writeRing(
775	  positions: Float32Array,
776	  normals: Float32Array,
777	  ring: number,
778	  cx: number, cy: number, cz: number,
779	  tx: number, ty: number, tz: number,
780	  ax: number, ay: number, az: number,
781	) {
782	  const halfW = BEAD_WIDTH_MM / 2;
783	  const halfH = BEAD_HEIGHT_MM / 2;
784	  // Axe de buse rendu orthogonal à la tangente ; s'il lui est parallèle (déplacement le long
785	  // de la buse), n'importe quelle perpendiculaire convient.
786	  let ux = ax, uy = ay, uz = az;
787	  const dot = ux * tx + uy * ty + uz * tz;
788	  ux -= dot * tx; uy -= dot * ty; uz -= dot * tz;
789	  let len = Math.hypot(ux, uy, uz);
790	  if (len < 1e-6) {
791	    ux = -ty; uy = tx; uz = 0;
792	    len = Math.hypot(ux, uy, uz);
793	    if (len < 1e-6) { ux = 0; uy = -tz; uz = ty; len = Math.hypot(uy, uz); }
794	  }
795	  ux /= len; uy /= len; uz /= len;
796	  // Côté = tangente × axe.
797	  const sx = ty * uz - tz * uy;
798	  const sy = tz * ux - tx * uz;
799	  const sz = tx * uy - ty * ux;
800	
801	  for (let i = 0; i < TUBE_SIDES; i++) {
802	    const v = (ring * TUBE_SIDES + i) * 3;
803	    const cs = RING_COS[i], sn = RING_SIN[i];
804	    positions[v] = cx + sx * halfW * cs + ux * halfH * sn;
805	    positions[v + 1] = cy + sy * halfW * cs + uy * halfH * sn;
806	    positions[v + 2] = cz + sz * halfW * cs + uz * halfH * sn;
807	    // Normale d'ellipse : gradient (cos/a, sin/b) dans le repère (côté, axe).
808	    let nx = sx * cs / halfW + ux * sn / halfH;
809	    let ny = sy * cs / halfW + uy * sn / halfH;
810	    let nz = sz * cs / halfW + uz * sn / halfH;
811	    const nl = Math.hypot(nx, ny, nz) || 1;
812	    nx /= nl; ny /= nl; nz /= nl;
813	    normals[v] = nx;
814	    normals[v + 1] = ny;
815	    normals[v + 2] = nz;
816	  }
817	}
