819	/** Donne à un sous-maillage affiché par préfixe (`indexCount`) une boîte englobante propre. */
820	function finalizePathMesh(mesh: BABYLON.Mesh) {
821	  // Tant que `indexCount` couvre toute la géométrie, Babylon traite le sous-maillage comme
822	  // « global » et lui prête la boîte englobante du maillage ; dès qu'on n'en affiche qu'un
823	  // préfixe, il lit sa boîte propre — jamais créée, d'où un crash dans le tri des objets
824	  // transparents qui arrêtait la boucle de rendu. On lui en donne une une fois pour toutes :
825	  // celle de la trajectoire complète, qui englobe n'importe quel préfixe (pas de
826	  // `refreshBoundingInfo`, qui reparcourrait les indices à chaque rotation du plateau).
827	  const { minimum, maximum } = mesh.getBoundingInfo();
828	  mesh.subMeshes[0].setBoundingInfo(new BABYLON.BoundingInfo(minimum.clone(), maximum.clone()));
829	  mesh.isPickable = false;
830	  mesh.alwaysSelectAsActiveMesh = true;
831	}
