856	    if (include(k)) capacity += segments[k] + 1;
857	  }
858	  if (capacity === 0) return { mesh: null, cumIndices, indicesPerStep };
859	
860	  // Passe 1 : échantillons le long de la trajectoire — centre du cordon, axe de buse, mouvement
861	  // propriétaire et début de tube (pas de sous-segment qui le relie au précédent).
862	  const centers = new Float32Array(capacity * 3);
863	  const axes = new Float32Array(capacity * 3);
864	  const owner = new Uint32Array(capacity);
865	  const stripStart = new Uint8Array(capacity);
866	  const tip = new BABYLON.Vector3();
867	  const ax = new BABYLON.Vector3();
868	  const halfH = BEAD_HEIGHT_MM / 2;
869	  let count = 0;
