949	/** Construit un LinesMesh (repère plateau) des mouvements retenus par `include`, dans l'ordre du
950	 * fichier. N'importe quel préfixe s'affiche ensuite en changeant `indexCount`. */
951	function buildPathMesh(
952	  name: string,
953	  parsed: ParsedGCode,
954	  sampler: PathSampler,
955	  include: (k: number) => boolean,
956	  color: BABYLON.Color3,
957	  scene: BABYLON.Scene,
958	): PathMesh {
959	  const { moves } = parsed;
960	  const { segments } = sampler;
961	  let vertexTotal = 0;
962	  for (let k = 1; k < moves.length; k++) {
963	    if (include(k)) vertexTotal += segments[k] + 1;
964	  }
965	
966	  const cumIndices = new Uint32Array(moves.length);
967	  if (vertexTotal === 0) return { mesh: null, cumIndices, indicesPerStep: 2 };
968	
969	  const positions = new Float32Array(vertexTotal * 3);
970	  const indices = new Uint32Array((vertexTotal - 1) * 2);
971	  const tip = new BABYLON.Vector3();
972	  let v = 0;
973	  let idx = 0;
974	
975	  for (let k = 1; k < moves.length; k++) {
976	    if (include(k)) {
977	      const n = segments[k];
978	      for (let s = 0; s <= n; s++) {
979	        sampler.tip(k, s / n, tip);
980	        positions[v * 3] = tip.x;
981	        positions[v * 3 + 1] = tip.y;
982	        positions[v * 3 + 2] = tip.z;
983	        if (s > 0) {
984	          indices[idx++] = v - 1;
985	          indices[idx++] = v;
986	        }
987	        v++;
988	      }
989	    }
990	    cumIndices[k] = idx;
991	  }
992	
993	  const mesh = new BABYLON.LinesMesh(name, scene);
994	  const data = new BABYLON.VertexData();
995	  data.positions = positions;
996	  data.indices = indices.subarray(0, idx);
997	  data.applyToMesh(mesh);
998	  mesh.color = color;
999	  mesh.alpha = 0.85;
1000	  finalizePathMesh(mesh);
1001	  return { mesh, cumIndices, indicesPerStep: 2 };
1002	}
