1004	/** Sphères (instances légères) aux positions de fin des mouvements `at`. */
1005	function buildMarkerMesh(
1006	  name: string,
1007	  at: Uint32Array,
1008	  sampler: PathSampler,
1009	  color: BABYLON.Color3,
1010	  scene: BABYLON.Scene,
1011	) {
1012	  if (!at.length) return null;
1013	  const mesh = BABYLON.MeshBuilder.CreateSphere(name, { diameter: MARKER_DIAMETER_MM, segments: 6 }, scene);
1014	  const material = new BABYLON.StandardMaterial(`${name}Mat`, scene);
1015	  material.disableLighting = true;
1016	  material.emissiveColor = color;
1017	  mesh.material = material;
1018	  const matrices = new Float32Array(at.length * 16);
1019	  const p = new BABYLON.Vector3();
1020	  const m = new BABYLON.Matrix();
1021	  for (let j = 0; j < at.length; j++) {
1022	    sampler.tip(at[j], 1, p);
1023	    BABYLON.Matrix.TranslationToRef(p.x, p.y, p.z, m);
1024	    m.copyToArray(matrices, j * 16);
1025	  }
1026	  mesh.thinInstanceSetBuffer('matrix', matrices, 16, true);
1027	  mesh.isPickable = false;
1028	  mesh.alwaysSelectAsActiveMesh = true;
1029	  return mesh;
