1032	/** Nombre d'éléments de `sorted` (croissant) inférieurs ou égaux à `t`. */
1033	function countUpTo(sorted: Uint32Array, t: number) {
1034	  let lo = 0, hi = sorted.length;
1035	  while (lo < hi) {
1036	    const mid = (lo + hi) >> 1;
1037	    if (sorted[mid] <= t) lo = mid + 1; else hi = mid;
1038	  }
1039	  return lo;
1040	}
