305	    };
306	    const onDragOver = (e: DragEvent) => {
307	      if (!hasFiles(e)) return;
308	      e.preventDefault();
309	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
310	    };
311	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
312	    const onDragLeave = (e: DragEvent) => {
313	      if (!hasFiles(e)) return;
314	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
315	      if (dragDepthRef.current === 0) setIsDragging(false);
316	    };
317	    const onDrop = (e: DragEvent) => {
318	      if (!hasFiles(e)) return;
319	      e.preventDefault();
320	      dragDepthRef.current = 0;
321	      setIsDragging(false);
322	      const file = e.dataTransfer?.files?.[0];
323	      if (file) loadFileRef.current(file);
324	    };
325	    window.addEventListener('dragenter', onDragEnter);
326	    window.addEventListener('dragover', onDragOver);
327	    window.addEventListener('dragleave', onDragLeave);
328	    window.addEventListener('drop', onDrop);
329	    return () => {
330	      window.removeEventListener('dragenter', onDragEnter);
331	      window.removeEventListener('dragover', onDragOver);
332	      window.removeEventListener('dragleave', onDragLeave);
333	      window.removeEventListener('drop', onDrop);
334	      dragDepthRef.current = 0;
335	      setIsDragging(false);
336	    };
337	  }, [active]);
