339	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
340	  // Viewport mis à jour immédiatement ; l'état React (qui redessine toute la page) au plus une fois
341	  // par image, pour qu'un glisser envoyant plusieurs événements par image reste fluide.
342	  const seekSyncRafRef = useRef(0);
343	  const seek = (value: number) => {
344	    setIsPlaying(false);
345	    tRef.current = value;
346	    dispatchTime(value);
347	    if (seekSyncRafRef.current) return;
348	    seekSyncRafRef.current = requestAnimationFrame(() => {
349	      seekSyncRafRef.current = 0;
350	      setT(tRef.current);
351	    });
352	  };
353	
354	  /** Lecture/pause ; repart du début si la lecture est au bout. */
355	  const togglePlay = () => {
356	    const parsed = parsedRef.current;
357	    if (!parsed) return;
358	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
359	    setIsPlaying(!isPlaying);
360	  };
361	
362	  const parsed = parsedRef.current;
363	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
364	  const current = parsed ? stateAt(parsed.moves, t) : null;
365	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
366	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
367	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
368	
369	  return {
370	    fileInfo,
371	    t,
372	    lastIndex,
373	    current,
374	    currentMove,
375	    isPlaying,
376	    togglePlay,
377	    seek,
378	    speed,
379	    setSpeed,
380	    lineVisibility,
381	    setLineVisible,
382	    showFullHead,
383	    setShowFullHead,
384	    isDragging,
385	    isLoading,
386	    loadFile,
387	    openFilePicker,
388	    conversion,
389	    /** G-code 3 axes chargé, convertible en polaire (qu'il l'ait déjà été ou non), sinon null. */
390	    conversionSource: fileInfo && sourceRef.current
391	      ? {
392	        name: sourceRef.current.name,
393	        nonPlanar: sourceRef.current.parsed.nonPlanar,
394	        offPlateTraits: sourceRef.current.parsed.offPlate.traits,
395	      }
396	      : null,
397	    setOffPlateHighlight,
398	    convert,
399	    /** Seul un G-code polaire (natif Apex ou converti) s'exporte pour l'Apex. */
400	    canExport: fileInfo?.kind === 'polar' && conversion.status !== 'running',
401	    exportGCode,
402	    /** Conversion possible ici : application de bureau, ou serveur de développement Vite. */
403	    conversionAvailable: isConversionAvailable(),
