1059	/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
1060	export const GCODE_MESH_PREFIX = 'gcode';
1061	
1062	/** Le glTF est en mètres, la scène en millimètres. */
1063	const GLTF_TO_MM = 1000;
1064	/** Rotation du modèle de tête autour de l'axe de sa buse (radians) : tel qu'exporté, son axe de
1065	 * basculement B est perpendiculaire à celui de la machine (Z du repère tête, la tête penchant
1066	 * dans le plan radial XY). */
1067	const HEAD_MODEL_YAW = Math.PI / 2;
1068	
1069	
1070	/**
1071	 * Charge le modèle de la tête (aetheris-4.glb) sous `headNode`, pointe de buse à l'origine du
1072	 * noeud et corps vers +Y local. Le fichier est déjà posé debout sur la buse, mais le centre de
1073	 * la face de sortie de la buse (maillage « NOZZLE origin ») est légèrement décalé de son
1074	 * origine : on recale le modèle sur ce point plutôt que de faire confiance à l'origine.
1075	 * Chargé dans un conteneur et renommé AVANT l'ajout à la scène : Viewport3D trie les maillages
1076	 * par nom dès leur arrivée (capture du flou, sélection de modèles) et doit ignorer ceux du calque.
1077	 */
1078	async function loadHeadModel(scene: BABYLON.Scene, headNode: BABYLON.TransformNode, isDisposed: () => boolean) {
1079	  const container = await BABYLON.SceneLoader.LoadAssetContainerAsync('', headModelUrl, scene, null, '.glb');
1080	  if (isDisposed()) {
1081	    container.dispose();
1082	    return { loaded: false as const };
1083	  }
1084	  // Repérés AVANT le renommage ci-dessous (sur le nom d'origine du glTF, jamais reconstruit à
1085	  // partir du nom préfixé/modifié) et renvoyés tels quels à l'appelant (cf. `setFullHead`) : plus
1086	  // sûr qu'un `.includes('NOZZLE')` a posteriori sur des noms qui ont pu être transformés.
1087	  const nozzleMeshes = container.meshes.filter((m) => m.name.includes('NOZZLE'));
1088	  const prefix = `${GCODE_MESH_PREFIX}HeadModel_`;
1089	  for (const mesh of container.meshes) {
1090	    mesh.name = prefix + mesh.name;
1091	    mesh.isPickable = false;
1092	  }
1093	  for (const node of container.transformNodes) node.name = prefix + node.name;
1094	
1095	  const model = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModel`, scene);
1096	  model.scaling.setAll(GLTF_TO_MM);
1097	  for (const node of container.rootNodes) node.parent = model;
1098	
1099	  // Pointe de buse mesurée avec le modèle seul (non encore rattaché à la tête) : son repère
1100	  // monde n'est alors que l'échelle, donc la boîte monde est directement en repère tête.
1101	  const nozzle = container.meshes.find((m) => m.name.includes('NOZZLE origin'));
1102	  if (nozzle) {
1103	    const chain: BABYLON.Node[] = [];
1104	    for (let n: BABYLON.Node | null = nozzle; n; n = n.parent) chain.unshift(n);
1105	    for (const n of chain) (n as BABYLON.TransformNode).computeWorldMatrix(true);
1106	    const { minimumWorld: min, maximumWorld: max } = nozzle.getBoundingInfo().boundingBox;
1107	    model.position.set(-(min.x + max.x) / 2, -min.y, -(min.z + max.z) / 2);
1108	  }
1109	  // Rotation portée par un noeud intermédiaire, APRÈS le recalage : elle tourne autour de l'axe
1110	  // vertical passant par la pointe de buse, qui reste donc à l'origine.
1111	  const mount = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModelMount`, scene);
1112	  mount.rotation.y = HEAD_MODEL_YAW;
1113	  mount.parent = headNode;
1114	  model.parent = mount;
1115	  container.addAllToScene();
1116	  return { loaded: true as const, nozzleMeshes };
1117	}
