1130	/**
1131	 * Calque de prévisualisation G-code posé dans une scène existante. `parent` est le repère du
1132	 * plateau (origine au centre de sa surface) : Z = 0 du G-code y correspond.
1133	 */
1134	export function createGCodeLayer(
1135	  scene: BABYLON.Scene,
1136	  parent: BABYLON.TransformNode,
1137	  /** Appelé à chaque mise à jour de la rotation du plateau (radians), pour y caler du décor. */
1138	  onPlateRotation?: (rotationY: number) => void,
1139	): GCodeLayer {
1140	  const root = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Root`, scene);
1141	  root.parent = parent;
1142	  root.setEnabled(false);
1143	
1144	  // Repère tournant du plateau : toute la matière déposée en est enfant.
1145	  const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
1146	  plateNode.parent = root;
1147	
1148	  // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
1149	  // est ensuite orienté pour que ce corps penche de B vers +R. Primitives provisoires, remplacées
1150	  // par le vrai modèle (loadHeadModel) une fois chargé ; gardées en repli s'il échoue.
1151	  const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
1152	  headNode.parent = root;
1153	  headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
1154	
1155	  // Tête complète ou buse seule (cf. `setFullHead`) : simple bascule de visibilité par maillage,
1156	  // « NOZZLE » (nom du modèle réel, cf. loadHeadModel) faisant office de repère — pas de plan de
1157	  // coupe : plus simple, et jamais de coquille ouverte à boucher puisque chaque maillage garde ses
1158	  // propres faces fermées, jamais tronquées à mi-hauteur.
1159	  let fullHead = true;
1160	
1161	  const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
1162	  nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
1163	  nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
1164	  const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
1165	  nozzle.position.y = 4.5;
1166	  nozzle.material = nozzleMat;
1167	  nozzle.parent = headNode;
1168	  const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
1169	  bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
1170	  bodyMat.alpha = 0.55;
1171	  const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
1172	  body.position.y = 9 + 13;
1173	  body.material = bodyMat;
1174	  body.parent = headNode;
1175	  nozzle.isPickable = false;
1176	  body.isPickable = false;
1177	  // `body` (le corps de la tête) n'a pas de contrepartie « NOZZLE » : c'est lui qu'il faut masquer
1178	  // quand `fullHead` est faux, `nozzle` restant visible dans les deux cas (repli du modèle glTF,
1179	  // où seuls les maillages nommés NOZZLE restent visibles — cf. le `.then` ci-dessous).
1180	  body.setEnabled(fullHead);
1181	  headNode.setEnabled(false);
1182	
1183	  // Tête complète ou buse seule (cf. `setFullHead`), applicable aux deux états possibles de la
1184	  // tête : primitives de repli (nozzle/body, avant chargement du modèle ou s'il échoue) ou vrai
1185	  // modèle glTF (après, cf. le `.then` ci-dessous) — jamais les deux en même temps, l'un dispose
1186	  // l'autre. Sur le modèle réel, seuls les maillages de `headModelNozzleMeshes` (repérés une fois
1187	  // pour toutes à leur chargement par `loadHeadModel`, cf. plus bas — jamais reconstruits ici par
1188	  // un `.includes('NOZZLE')` sur un nom déjà transformé) restent visibles ; le reste (corps,
1189	  // radiateur, ventilateur, connecteurs…) est simplement désactivé — jamais de plan de coupe ni de
1190	  // bouchon à poser, chaque maillage garde ses propres faces, déjà fermées, intactes.
1191	  let headModelNozzleMeshes: BABYLON.AbstractMesh[] | null = null;
1192	  const applyHeadVisibility = () => {
1193	    if (!headModelNozzleMeshes) {
1194	      // Modèle glTF pas encore chargé (ou échec) : seules les primitives de repli existent.
1195	      if (!body.isDisposed()) body.setEnabled(fullHead);
1196	      return;
1197	    }
1198	    const nozzleSet = new Set<BABYLON.Node>(headModelNozzleMeshes);
1199	    // `isEnabled()` d'un maillage suit toute sa chaîne d'ancêtres (cf. Node.isEnabled) : le loader
1200	    // glTF parente souvent tout sous un noeud technique (`__root__`) — le désactiver, lui, masque
1201	    // aussi ses enfants NOZZLE bien que LEUR propre drapeau reste actif. Jamais désactiver un
1202	    // ancêtre d'un maillage NOZZLE, donc, seulement les branches qui n'en contiennent aucun.
1203	    const ancestorsOfNozzle = new Set<BABYLON.Node>();
1204	    for (const nozzleMesh of headModelNozzleMeshes) {
1205	      for (let n: BABYLON.Node | null = nozzleMesh.parent; n && n !== headNode; n = n.parent) ancestorsOfNozzle.add(n);
1206	    }
1207	    for (const mesh of headNode.getChildMeshes()) {
1208	      if (!nozzleSet.has(mesh) && !ancestorsOfNozzle.has(mesh)) mesh.setEnabled(fullHead);
1209	    }
1210	  };
1211	
1212	  let disposed = false;
1213	  loadHeadModel(scene, headNode, () => disposed)
1214	    .then((result) => {
1215	      if (!result.loaded) return;
1216	      nozzle.dispose(false, true);
1217	      body.dispose(false, true);
1218	      headModelNozzleMeshes = result.nozzleMeshes;
1219	      applyHeadVisibility();
1220	    })
1221	    .catch((err) => console.warn('Modèle de tête G-code non chargé, primitives conservées :', err));
