1227	    LINE_TYPES.map((t) => [t.id, BABYLON.Color3.FromHexString(t.color)]),
1228	  ) as Record<LineTypeId, BABYLON.Color3>;
1229	  const beadMaterials = new Map<LineTypeId, BABYLON.StandardMaterial>();
1230	  for (const t of LINE_TYPES) {
1231	    if (t.kind !== 'extrusion') continue;
1232	    const mat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}BeadMat_${t.id}`, scene);
1233	    mat.diffuseColor = colors[t.id];
1234	    mat.emissiveColor = colors[t.id].scale(0.18);
1235	    mat.specularColor = new BABYLON.Color3(0.25, 0.25, 0.25);
1236	    mat.specularPower = 48;
1237	    mat.backFaceCulling = false;
1238	    beadMaterials.set(t.id, mat);
1239	  }
1240	
1241	  // Tronçon « vivant » : portion du mouvement en cours entre la dernière jonction déjà dessinée
