1243	  // chaque image — le tracé avance en continu sous la buse au lieu d'apparaître d'un bloc à la fin
1244	  // de chaque mouvement (ou sous-segment), sans alourdir la géométrie des maillages complets.
1245	  const livePositions = new Float32Array(2 * TUBE_SIDES * 3);
1246	  const liveNormals = new Float32Array(2 * TUBE_SIDES * 3);
1247	  const liveIndices: number[] = [];
1248	  for (let i = 0; i < TUBE_SIDES; i++) {
1249	    const i1 = (i + 1) % TUBE_SIDES;
