1357	        sampler.tip(next, f, liveB);
1358	        if (m.extruding) {
1359	          const dx = liveB.x - liveA.x, dy = liveB.y - liveA.y, dz = liveB.z - liveA.z;
1360	          const len = Math.hypot(dx, dy, dz);
1361	          if (len > 1e-6) {
1362	            sampler.axis(next, f0, liveAxA);
1363	            sampler.axis(next, f, liveAxB);
1364	            const halfH = BEAD_HEIGHT_MM / 2;
1365	            const tx = dx / len, ty = dy / len, tz = dz / len;
1366	            writeRing(livePositions, liveNormals, 0,
1367	              liveA.x - liveAxA.x * halfH, liveA.y - liveAxA.y * halfH, liveA.z - liveAxA.z * halfH,
1368	              tx, ty, tz, liveAxA.x, liveAxA.y, liveAxA.z);
1369	            writeRing(livePositions, liveNormals, 1,
1370	              liveB.x - liveAxB.x * halfH, liveB.y - liveAxB.y * halfH, liveB.z - liveAxB.z * halfH,
1371	              tx, ty, tz, liveAxB.x, liveAxB.y, liveAxB.z);
1372	            liveBead.updateVerticesData(BABYLON.VertexBuffer.PositionKind, livePositions);
1373	            liveBead.updateVerticesData(BABYLON.VertexBuffer.NormalKind, liveNormals);
1374	            liveBead.material = beadMaterials.get(m.type) ?? null;
1375	            showBead = true;
1376	          }
1377	        } else {
1378	          livePoints[0].copyFrom(liveA);
1379	          livePoints[1].copyFrom(liveB);
1380	          liveLine = BABYLON.MeshBuilder.CreateLines(liveLine.name, { points: livePoints, instance: liveLine });
1381	          liveLine.color = colors[type];
1382	          showLine = true;
1383	        }
1384	      }
1385	    }
1386	    liveBead.setEnabled(showBead);
1387	    liveLine.setEnabled(showLine);
1388	  };
1389	
1390	  const applyVisibility = () => {
1391	    for (const entry of paths) entry.mesh?.setEnabled(visibility[entry.type]);
1392	    for (const entry of markers) entry.mesh.setEnabled(visibility[entry.type]);
1393	    offPlatePath?.mesh?.setEnabled(highlightOffPlate);
1394	  };
1395	
1396	  const disposeAll = () => {
1397	    for (const entry of paths) entry.mesh?.dispose(false, false);
1398	    for (const entry of markers) entry.mesh.dispose(false, true);
1399	    offPlatePath?.mesh?.dispose(false, false);
1400	    paths = [];
1401	    markers = [];
1402	    offPlatePath = null;
1403	  };
1404	
1405	  return {
1406	    load(next) {
1407	      disposeAll();
1408	      parsed = next;
1409	      const { moves } = next;
1410	      const pathSampler = createSampler(next);
1411	      sampler = pathSampler;
1412	      segments = pathSampler.segments;
1413	
1414	      for (const t of LINE_TYPES) {
1415	        if (t.kind !== 'extrusion') continue;
1416	        const include = (k: number) => moves[k].type === t.id;
1417	        const built = buildBeadMesh(`${GCODE_MESH_PREFIX}Bead_${t.id}`, next, pathSampler, include, beadMaterials.get(t.id)!, scene);
1418	        paths.push({ ...built, type: t.id, include });
1419	      }
1420	      // Trajets à vide : tout mouvement sans dépôt hors essuyage (rétractions sur place comprises,
1421	      // de longueur nulle).
1422	      const travelInclude = (k: number) => !moves[k].extruding && moves[k].type !== 'wipe';
1423	      const wipeInclude = (k: number) => moves[k].type === 'wipe';
1424	      for (const [type, include] of [['travel', travelInclude], ['wipe', wipeInclude]] as const) {
1425	        const built = buildPathMesh(`${GCODE_MESH_PREFIX}Path_${type}`, next, pathSampler, include, colors[type], scene);
1426	        paths.push({ ...built, type, include });
1427	      }
1428	      for (const [type, at] of Object.entries(next.markers) as [LineTypeId, Uint32Array][]) {
1429	        const mesh = buildMarkerMesh(`${GCODE_MESH_PREFIX}Marker_${type}`, at, pathSampler, colors[type], scene);
1430	        if (mesh) markers.push({ type, mesh, at });
1431	      }
1432	      if (next.offPlate.moves.length) {
1433	        const flags = new Uint8Array(moves.length);
1434	        for (const k of next.offPlate.moves) flags[k] = 1;
1435	        const include = (k: number) => flags[k] === 1;
1436	        const built = buildBeadMesh(`${GCODE_MESH_PREFIX}OffPlate`, next, pathSampler, include, offPlateMat, scene);
1437	        offPlatePath = { ...built, type: 'custom', include };
1438	        if (offPlatePath.mesh) offPlatePath.mesh.parent = plateNode;
1439	      }
1440	      for (const entry of [...paths, ...markers]) {
1441	        if (entry.mesh) entry.mesh.parent = plateNode;
1442	      }
1443	      applyVisibility();
1444	
1445	      headNode.setEnabled(moves.length > 0);
1446	      time = moves.length - 1;
1447	      apply();
1448	    },
1449	    setTime(t) {
1450	      time = t;
1451	      apply();
1452	    },
1453	    setLineTypeVisibility(next) {
1454	      visibility = { ...next };
1455	      applyVisibility();
1456	    },
1457	    setOffPlateHighlight(show) {
1458	      highlightOffPlate = show;
1459	      applyVisibility();
1460	    },
1461	    setFullHead(show) {
1462	      fullHead = show;
1463	      applyHeadVisibility();
1464	    },
1465	    setEnabled(enabled) {
1466	      root.setEnabled(enabled);
1467	    },
1468	    getPlateRotation() {
1469	      return plateNode.rotation.y;
1470	    },
1471	    dispose() {
1472	      disposed = true;
1473	      disposeAll();
1474	      root.dispose(false, true);
1475	    },
1476	  };
1477	}

1	/**
2	 * Identification du logiciel qui a produit un G-code (« Généré le plus probablement par »).
3	 *
4	 * 1. Signature explicite en commentaire d'en-tête, quand le slicer en laisse une :
5	 *    `; generated by PrusaSlicer 2.7.1 on …` (Prusa, SuperSlicer, Orca, Anycubic Slicer Next,
6	 *    Creality Print, Simplify3D…), `;Generated with Cura_SteamEngine 5.4.0`, `; <IceSL …>`,
7	 *    `; BambuStudio 01.09.00.70`, `;Sliced by ideaMaker 4.4`…
8	 * 2. À défaut, déduction d'après le style des marqueurs de type de ligne, propre à chaque famille
9	 *    (`;TYPE:Inner wall` Orca/Bambu, `;TYPE:External perimeter` Prusa, `;TYPE:WALL-OUTER` Cura,
10	 *    `; feature outer perimeter` Simplify3D, `; <layer>` IceSL).
11	 */
12	
13	export interface GCodeGenerator {
14	  name: string;
15	  /** Vrai quand le nom est déduit du format plutôt que lu dans une signature explicite. */
16	  inferred: boolean;
17	}
18	
19	// Noms tels qu'écrits dans les fichiers → nom commercial.
20	const DISPLAY_NAMES: [RegExp, string][] = [
21	  [/^AnycubicSlicerNext\b/i, 'Anycubic Slicer Next'],
22	  [/^Creality[ _]?Print\b/i, 'Creality Print'],
23	  [/^BambuStudio\b/i, 'Bambu Studio'],
24	  [/^Orca[ _]?Slicer\b/i, 'OrcaSlicer'],
25	  [/^Cura_SteamEngine\b/i, 'UltiMaker Cura'],
26	  [/^Simplify3D(\(R\))?/i, 'Simplify3D'],
27	  [/^ElegooSlicer\b/i, 'Elegoo Slicer'],
28	  [/^SuperSlicer\b/i, 'SuperSlicer'],
29	  [/^PrusaSlicer\b/i, 'PrusaSlicer'],
30	];
31	
32	/** « Creality_Print V7.1.0.4414 » → « Creality Print 7.1.0.4414 ». */
33	function displayName(raw: string) {
34	  let name = raw.trim();
35	  for (const [re, pretty] of DISPLAY_NAMES) {
36	    if (re.test(name)) { name = name.replace(re, pretty); break; }
37	  }
38	  return name
39	    .replace(/_/g, ' ')
40	    .replace(/\s+Version\s+/i, ' ')
41	    .replace(/\s+v(?=\d)/i, ' ')
42	    .replace(/\s+/g, ' ')
43	    .trim();
44	}
45	
46	const MONTHS: Record<string, string> = {
47	  jan: 'janvier', feb: 'février', mar: 'mars', apr: 'avril', may: 'mai', jun: 'juin',
48	  jul: 'juillet', aug: 'août', sep: 'septembre', oct: 'octobre', nov: 'novembre', dec: 'décembre',
49	};
50	
51	/** Date de compilation au format `__DATE__` (« Jul  9 2025 ») → « 9 juillet 2025 ». */
52	const frenchDate = (month: string, day: string, year: string) =>
53	  `${parseInt(day, 10)} ${MONTHS[month.toLowerCase()] ?? month} ${year}`;
54	
55	const SIGNATURES:[RegExp, (m: RegExpExecArray) => string][] = [
56	  [/generated with\s+(cura_steamengine|cura)\s*([\d.]*)/i, (m) => `UltiMaker Cura ${m[2]}`],
57	  [/generated by\s+(.+?)(?:\s+on\s+\d{4}-\d{2}-\d{2}.*)?$/i, (m) => displayName(m[1])],
58	  [/^\s*<IceSL\s+([A-Za-z]{3})\s+(\d{1,2})\s+(\d{4})/i, (m) => `IceSL (version du ${frenchDate(m[1], m[2], m[3])})`],
59	  [/^\s*(BambuStudio|OrcaSlicer|ElegooSlicer)\s+v?([\d.]+)\s*$/i, (m) => displayName(`${m[1]} ${m[2]}`)],
60	  [/sliced by\s+(ideamaker[\s\d.]*)/i, (m) => m[1].replace(/ideamaker/i, 'ideaMaker')],
61	  [/KISSlicer/i, () => 'KISSlicer'],
62	  [/Kiri:Moto/i, () => 'Kiri:Moto'],
63	  [/MatterSlice/i, () => 'MatterControl'],
64	  [/FlashPrint/i, () => 'FlashPrint'],
65	];
66	
67	/** Signature explicite contenue dans un commentaire (sans le `;`), ou null. */
68	export function detectGeneratorSignature(comment: string): string | null {
69	  for (const [re, format] of SIGNATURES) {
70	    const m = re.exec(comment);
71	    if (m) return format(m).trim();
72	  }
73	  return null;
74	}
75	
76	const normalize = (name: string) => name.toLowerCase().replace(/[^a-z]/g, '');
77	
78	const ORCA_FEATURES = new Set([
79	  'innerwall', 'outerwall', 'overhangwall', 'sparseinfill', 'internalsolidinfill',
80	  'topsurface', 'bottomsurface', 'internalbridge', 'gapinfill',
81	]);
82	const PRUSA_FEATURES = new Set([
83	  'perimeter', 'externalperimeter', 'overhangperimeter', 'internalinfill', 'solidinfill',
84	  'topsolidinfill', 'bridgeinfill', 'gapfill', 'skirtbrim', 'supportmaterial', 'wipetower',
85	]);
86	
87	/**
88	 * Famille de slicer d'après le nom brut d'un marqueur de type (`;TYPE:<nom>`), ou null s'il ne
89	 * permet pas de trancher (« Custom », « Bridge »… communs à plusieurs familles).
90	 */
91	export function guessGeneratorFromFeature(rawName: string, simplify3DStyle: boolean): string | null {
92	  if (simplify3DStyle) return 'Simplify3D';
93	  const raw = rawName.trim();
94	  if (/^[A-Z]+(-[A-Z]+)*$/.test(raw)) return 'UltiMaker Cura ou dérivé';
95	  const key = normalize(raw);
96	  if (ORCA_FEATURES.has(key)) return 'OrcaSlicer / Bambu Studio ou dérivé';
97	  if (PRUSA_FEATURES.has(key)) return 'PrusaSlicer ou dérivé';
98	  return null;
99	}
