17	const formatNumber = (value: number, digits: number) => value.toFixed(digits).replace('.', ',');
18	
19	/** « 8 m 45 s », « 12 s » ; heures sans secondes (« 1 h 12 m ») pour tenir dans la colonne. */
20	const formatDuration = (seconds: number) => {
21	  const total = Math.round(seconds);
22	  if (total === 0) return '< 1 s';
23	  const h = Math.floor(total / 3600);
24	  const m = Math.floor((total % 3600) / 60);
25	  const s = total % 60;
26	  if (h > 0) return `${h} h ${m} m`;
27	  return m > 0 ? `${m} m ${s} s` : `${s} s`;
28	};
