30	// Même cascade d'apparition que GCodeSpeedSelector (fondu-montée, easing « standard » Material).
31	const containerVariants = {
32	  hidden: {},
33	  visible: { transition: { staggerChildren: 0.02 } },
34	};
35	const itemVariants = {
36	  hidden: { opacity: 0, y: 6 },
