52	        <span className={styles.numeric}>Pourcentage</span>
53	        <span className={styles.numeric}>Longueur</span>
54	        <span className={styles.numeric}>Poids</span>
55	        <span />
56	      </motion.div>
57	  
58	      <div className={styles.rows}>
59	        {LINE_TYPES.map((type) => {
60	          const stat = fileInfo?.lineStats[type.id];
61	          const hasTime = !!stat && stat.time > 0;
