1	import React, { useRef, useState } from 'react';
2	import { motion } from 'framer-motion';
3	import clsx from 'clsx';
4	import { GCODE_SPEED_OPTIONS } from '@/hooks/use-gcode-preview';
5	import styles from './GCodeSpeedSelector.module.scss';
6	
7	interface GCodeSpeedSelectorProps {
8	  /** Multiplicateur du temps machine réel (cf. GCODE_SPEED_OPTIONS). */
9	  speed: number;
10	  setSpeed: (speed: number) => void;
11	  /** Tête d'outil complète (glTF entier) ou tronquée à la buse (cf. apex-gcode-show-full-head). */
12	  showFullHead: boolean;
13	  setShowFullHead: (show: boolean) => void;
14	}
15	
16	const TOOLTIP = {
17	  title: "Vitesse d'impression",
18	  desc: 'Vitesse de lecture de la prévisualisation, en multiple de la vitesse réelle de la machine (avances F du G-code).',
19	};
20	
21	const HEAD_TOOLTIP = {
22	  title: "Tête d'outil complète",
23	  desc: "Décochez pour ne plus afficher que la buse, en masquant le reste de la tête d'outil.",
24	};
