26	// Curseur en échelle logarithmique entre le plus petit et le plus grand préréglage : chaque
27	// préréglage (×4 du précédent) est ainsi à intervalle régulier sur la piste, et les faibles
28	// vitesses restent précises.
29	const MIN_SPEED = GCODE_SPEED_OPTIONS[0];
30	const MAX_SPEED = GCODE_SPEED_OPTIONS[GCODE_SPEED_OPTIONS.length - 1];
31	const LOG_RANGE = Math.log(MAX_SPEED / MIN_SPEED);
32	const speedToRatio = (speed: number) => Math.log(speed / MIN_SPEED) / LOG_RANGE;
33	const ratioToSpeed = (ratio: number) => MIN_SPEED * Math.exp(ratio * LOG_RANGE);
34	
35	const formatSpeed = (speed: number) => {
36	  if (speed < 1) return `${speed.toFixed(2)}×`;
37	  if (speed < 10) return `${speed.toFixed(1)}×`;
38	  return `${Math.round(speed)}×`;
39	};
40	
41	// Apparition à l'entrée dans l'espace Prévisualisation : jamais d'un coup avec le panneau qui le
42	// porte (cf. previewPanelFooter dans CategoriesSidebar.module.scss, qui ne fait qu'apparaître avec
43	// lui) — case puis curseur+préréglages, l'un après l'autre en cascade, même vocabulaire que la
44	// cascade de contenu de ModelingSidebar (CONTENT_STAGGER_MS/contentGroupVariants) : fondu-montée,
45	// easing "standard" Material.
46	const REVEAL_STAGGER_S = 0.09;
47	const REVEAL_ITEM_DURATION_S = 0.22;
48	const revealContainerVariants = {
49	  hidden: { transition: { staggerChildren: REVEAL_STAGGER_S } },
50	  visible: { transition: { staggerChildren: REVEAL_STAGGER_S } },
51	};
52	const revealItemVariants = {
53	  hidden: { opacity: 0, y: 6 },
54	  visible: { opacity: 1, y: 0, transition: { duration: REVEAL_ITEM_DURATION_S, ease: [0.4, 0, 0.2, 1] as const } },
55	};
56	// Décalage jusqu'à ce que .sliderGroup (second groupe de la cascade, cf. staggerChildren
57	// ci-dessus) ait lui-même fini d'apparaître : les trois phases du curseur (cf. plus bas) doivent
58	// se jouer une fois ce groupe pleinement visible, jamais en même temps que son propre fondu-montée
