78	const SLIDER_GLIDE_DELAY_S = SLIDER_HANDLE_DELAY_S + SLIDER_HANDLE_APPEAR_S;
79	const SLIDER_GLIDE_S = 0.5;
80	const SLIDER_GLIDE_EASE = [0.16, 1, 0.3, 1] as const;
81	
82	/**
83	 * Sélecteur de vitesse de lecture de l'espace Prévisualisation, posé au bas du panneau du bas de
84	 * CategoriesSidebar (cf. `previewLowerContent`) : curseur continu, puis contrôle segmenté sur
85	 * GCODE_SPEED_OPTIONS juste en dessous.
86	 */
87	export const GCodeSpeedSelector: React.FC<GCodeSpeedSelectorProps> = ({
88	  speed,
89	  setSpeed,
